  int _nudgesLeft = maxToolNudgesPerTurn;

  /// Nudges sent overall — the dedup/cap test seam's observable.
  int _nudgesSent = 0;

  /// Refills the per-turn nudge budget (issue #1185 E2).
  void resetToolNudges() {
    _nudgesLeft = maxToolNudgesPerTurn;
